import type { Node } from "postcss";
import type { PostcssResult } from "stylelint";
import { type Syntax } from "../../syntaxes/index.ts";
/** A neighboring rule: its directory name and the primaries it accepts. */
export type NeighborRule = {
    name: string;
    options: string[];
};
/**
 * Reads some neighbors' settings in run order, as {@link listedInRunOrder} lists them; whether a copy's fix is off travels with its option.
 * @param node - A node of the root the rules read.
 * @param result - The PostCSS result carrying the configuration.
 * @param rules - The neighbors by the caller's keys; a key may stand empty.
 * @returns Key, option, whether the fix is off and the configured name, per neighbor, in run order.
 */
export declare function neighborSettings<Key extends string>(node: Node, result: PostcssResult, rules: Partial<Record<Key, NeighborRule>>): [Key, string, boolean, string][];
/**
 * Asks whether a whitespace option speaks of a text: `always` and `never` always, the `-line` ones by the text's lines.
 * @param option - The whitespace keyword a rule is configured with.
 * @param isSingleLine - Whether the text is one line, asked only where the option turns on it.
 * @returns True where the option speaks of the text.
 */
export declare function speaksOf(option: string, isSingleLine: () => boolean): boolean;
/** A neighboring rule whose primary is a keyword or `true`, read with its secondaries. */
export type NeighborRuleSetting = {
    name: string;
    options: (string | true)[];
};
/** One copy of a neighbor, read whole: its option, whether its fix is off, its secondaries, the name it is configured under and the syntax of that name's namespace. */
export type NeighborCopy = {
    option: string | true;
    fixDisabled: boolean;
    secondary: Record<string, unknown>;
    name: string;
    syntax: Syntax;
};
/**
 * Reads the copy of one neighbor that reads the root whole, secondaries included, under whichever namespace it is configured, as {@link neighborSettings} finds it.
 * @param node - A node of the root the rules read.
 * @param result - The PostCSS result carrying the configuration.
 * @param rule - The neighbor and the primaries it accepts.
 * @returns The copy, in a list of one; none where the neighbor is unlisted, refuses its primary, or is listed only under namespaces refusing the root.
 */
export declare function neighborCopies(node: Node, result: PostcssResult, rule: NeighborRuleSetting): NeighborCopy[];
